$memoryActiveConfig=[IO.File]::ReadAllText((Join-Path (Split-Path $PSScriptRoot -Parent) 'config.toml')); if ($memoryActiveConfig -match '(?m)^\s*llm_provider\s*=\s*"(opencode|openai-compat)"\s*(?:#.*)?$') { $memoryRelayProvider=$Matches[1]; $memoryKeyPath=Join-Path $PSScriptRoot 'relay-api-key.txt'; if (!(Test-Path -LiteralPath $memoryKeyPath)) { throw 'Relay API key file is missing.' }; $memoryRelayKey=[IO.File]::ReadAllText($memoryKeyPath).Trim(); if (!$memoryRelayKey -or $memoryRelayKey -eq 'PASTE_API_KEY_HERE' -or $memoryRelayKey -match '\s') { throw 'Fill relay-api-key.txt with the API key only, on one line.' }; if ($memoryRelayProvider -eq 'openai-compat') { $env:LLM_API_KEY=$memoryRelayKey } else { $env:OPENCODE_API_KEY=$memoryRelayKey }; Remove-Variable memoryRelayKey,memoryRelayProvider }; Remove-Variable memoryActiveConfig
